//! 精简文本解码模块（仅提供 CSV / TSV 解析所需的 UTF-16LE/BE 与 GB18030 解码）。
//!
//! 避免引入 `encoding_rs` 全量码表（Big5 / Shift_JIS / EUC-JP / EUC-KR 等约 81.5 KiB 冗余静态表
//! 及对应编码器），仅保留 UTF-16LE/BE 与 GB18030 解码所需最小逻辑与映射表。
//
// GB18030/GBK/GB2312 mapping tables and decoding logic are derived from `encoding_rs`
// (Copyright Mozilla Foundation, licensed under Apache-2.0 OR MIT) and the WHATWG
// Encoding Standard data files (Copyright WHATWG, BSD-3-Clause).

use std::borrow::Cow;

/// 解码 UTF-16LE（不含 BOM），返回 `(解码文本, 是否出现非法代理项或孤立尾字节)`。
pub(crate) fn decode_utf16_le(bytes: &[u8]) -> (String, bool) {
    decode_utf16(bytes, false)
}

/// 解码 UTF-16BE（不含 BOM），返回 `(解码文本, 是否出现非法代理项或孤立尾字节)`。
pub(crate) fn decode_utf16_be(bytes: &[u8]) -> (String, bool) {
    decode_utf16(bytes, true)
}

fn decode_utf16(bytes: &[u8], big_endian: bool) -> (String, bool) {
    let mut chunks = bytes.chunks_exact(2);
    let mut out = String::with_capacity(bytes.len() / 2);
    let mut had_errors = false;
    let units = chunks.by_ref().map(|pair| {
        if big_endian {
            u16::from_be_bytes([pair[0], pair[1]])
        } else {
            u16::from_le_bytes([pair[0], pair[1]])
        }
    });
    for decoded in char::decode_utf16(units) {
        match decoded {
            Ok(ch) => out.push(ch),
            Err(_) => {
                had_errors = true;
                out.push('\u{FFFD}');
            }
        }
    }
    if !chunks.remainder().is_empty() {
        had_errors = true;
        out.push('\u{FFFD}');
    }
    (out, had_errors)
}

/// 按 WHATWG GB18030（含 GB18030-2022）规范解码字节切片，返回 `(解码文本, 是否存在非法序列)`。
pub(crate) fn decode_gb18030(bytes: &[u8]) -> (Cow<'_, str>, bool) {
    if bytes.is_ascii() {
        // ASCII 字节全部小于 0x80，必然是合法 UTF-8，零拷贝返回
        if let Ok(s) = std::str::from_utf8(bytes) {
            return (Cow::Borrowed(s), false);
        }
    }

    let mut out = String::with_capacity(bytes.len());
    let mut had_errors = false;
    let mut i = 0;

    while i < bytes.len() {
        let ascii_start = i;
        while i < bytes.len() && bytes[i] < 0x80 {
            i += 1;
        }
        if i > ascii_start {
            if let Ok(ascii) = std::str::from_utf8(&bytes[ascii_start..i]) {
                out.push_str(ascii);
            }
            continue;
        }

        let b1 = bytes[i];
        if b1 == 0x80 {
            out.push('\u{20AC}');
            i += 1;
            continue;
        }
        let Some(first) = b1.checked_sub(0x81) else {
            had_errors = true;
            out.push('\u{FFFD}');
            i += 1;
            continue;
        };
        if first > 0xFE - 0x81 {
            // b1 == 0xFF
            had_errors = true;
            out.push('\u{FFFD}');
            i += 1;
            continue;
        }

        let Some(&b2) = bytes.get(i + 1) else {
            had_errors = true;
            out.push('\u{FFFD}');
            i += 1;
            continue;
        };

        if (0x30..=0x39).contains(&b2) {
            let second = b2 - 0x30;
            let Some(&b3) = bytes.get(i + 2) else {
                // 4 字节序列在 EOF 处截断：整个未完成序列作为一个整体报错并消费
                had_errors = true;
                out.push('\u{FFFD}');
                i += 2;
                continue;
            };
            let Some(third) = b3.checked_sub(0x81) else {
                had_errors = true;
                out.push('\u{FFFD}');
                i += 1;
                continue;
            };
            if third > 0xFE - 0x81 {
                had_errors = true;
                out.push('\u{FFFD}');
                i += 1;
                continue;
            }
            let Some(&b4) = bytes.get(i + 3) else {
                // 4 字节序列在 EOF 处截断：整个未完成序列作为一个整体报错并消费
                had_errors = true;
                out.push('\u{FFFD}');
                i += 3;
                continue;
            };
            if !(0x30..=0x39).contains(&b4) {
                had_errors = true;
                out.push('\u{FFFD}');
                i += 1;
                continue;
            }
            let fourth = b4 - 0x30;
            let pointer = usize::from(first) * (10 * 126 * 10)
                + usize::from(second) * (10 * 126)
                + usize::from(third) * 10
                + usize::from(fourth);
            if pointer == 7457 {
                out.push('\u{E7C7}');
            } else if pointer <= 39419 {
                let bmp = gb18030_range_decode(pointer as u16);
                out.push(char::from_u32(u32::from(bmp)).unwrap_or('\u{FFFD}'));
            } else if (189_000..=1_237_575).contains(&pointer) {
                let code = (pointer - (189_000 - 0x1_0000)) as u32;
                out.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
            } else {
                had_errors = true;
                out.push('\u{FFFD}');
            }
            i += 4;
            continue;
        }

        // 双字节序列
        if let Some((ch, consumed)) = decode_two_byte(first, b2) {
            out.push(ch);
            i += consumed;
        } else {
            had_errors = true;
            out.push('\u{FFFD}');
            i += if b2 < 0x80 { 1 } else { 2 };
        }
    }

    (Cow::Owned(out), had_errors)
}

fn decode_two_byte(first: u8, second: u8) -> Option<(char, usize)> {
    if first >= 0x20 {
        let trail = second.wrapping_sub(0xA1);
        if trail <= 0xFE - 0xA1 {
            let hanzi_lead = first.wrapping_sub(0x2F);
            let code = if hanzi_lead < 0x77 - 0x2F {
                let ptr = usize::from(hanzi_lead) * 94 + usize::from(trail);
                GB2312_HANZI.get(ptr).copied()?
            } else if first == 0x20 {
                GB2312_SYMBOLS.get(usize::from(trail)).copied()?
            } else if first == 0x25 {
                let idx = trail.wrapping_sub(63);
                if usize::from(idx) < GB2312_SYMBOLS_AFTER_GREEK.len() {
                    GB2312_SYMBOLS_AFTER_GREEK[usize::from(idx)]
                } else {
                    let ptr = usize::from(first - 0x21) * 94 + usize::from(trail);
                    gb2312_other_decode(ptr as u16)
                }
            } else if first == 0x27 && usize::from(trail) < GB2312_PINYIN.len() {
                GB2312_PINYIN[usize::from(trail)]
            } else if first > 0x76 {
                (0xE234 + usize::from(first - 0x77) * 94 + usize::from(trail)) as u16
            } else {
                let ptr = usize::from(first - 0x21) * 94 + usize::from(trail);
                gb2312_other_decode(ptr as u16)
            };
            return char::from_u32(u32::from(code)).map(|c| (c, 2));
        }

        // GB2312 左侧 GBK 扩展区：second 范围为 0x40..=0x7E 或 0x80..=0xA0
        let trail_offset = if (0x40..=0x7E).contains(&second) {
            second - 0x40
        } else if (0x80..=0xA0).contains(&second) {
            second - 0x41
        } else {
            return None;
        };
        let left_lead = first - 0x20;
        let left_pointer = usize::from(left_lead) * (190 - 94) + usize::from(trail_offset);
        let gbk_left_ideograph_pointer = left_pointer.wrapping_sub((0x29 - 0x20) * (190 - 94));
        let code = if gbk_left_ideograph_pointer < ((0x7D - 0x29) * (190 - 94) - 5) {
            gbk_left_ideograph_decode(gbk_left_ideograph_pointer as u16)
        } else if left_pointer < (0x29 - 0x20) * (190 - 94) {
            gbk_other_decode(left_pointer as u16)
        } else {
            let bottom_pointer = left_pointer - ((0x7D - 0x20) * (190 - 94) - 5);
            GBK_BOTTOM.get(bottom_pointer).copied()?
        };
        return char::from_u32(u32::from(code)).map(|c| (c, 2));
    }

    // GB2312 上方 GBK 汉字区：first < 0x20，second 范围为 0x40..=0x7E 或 0x80..=0xFE
    let trail_offset = if (0x40..=0x7E).contains(&second) {
        second - 0x40
    } else if (0x80..=0xFE).contains(&second) {
        second - 0x41
    } else {
        return None;
    };
    let pointer = usize::from(first) * 190 + usize::from(trail_offset);
    let code = gbk_top_ideograph_decode(pointer as u16);
    char::from_u32(u32::from(code)).map(|c| (c, 2))
}

fn map_with_ranges(haystack: &[u16], other: &[u16], needle: u16) -> u16 {
    match haystack.binary_search(&needle) {
        Ok(i) => other.get(i).copied().unwrap_or(0xFFFD),
        Err(i) => {
            if let Some(prev) = i.checked_sub(1) {
                if let (Some(&base_out), Some(&base_in)) = (other.get(prev), haystack.get(prev)) {
                    return base_out.wrapping_add(needle - base_in);
                }
            }
            0xFFFD
        }
    }
}

fn gb18030_range_decode(pointer: u16) -> u16 {
    map_with_ranges(&GB18030_RANGE_POINTERS, &GB18030_RANGE_OFFSETS, pointer)
}

fn gbk_top_ideograph_decode(pointer: u16) -> u16 {
    map_with_ranges(
        &GBK_TOP_IDEOGRAPH_POINTERS,
        &GBK_TOP_IDEOGRAPH_OFFSETS,
        pointer,
    )
}

fn gbk_left_ideograph_decode(pointer: u16) -> u16 {
    map_with_ranges(
        &GBK_LEFT_IDEOGRAPH_POINTERS,
        &GBK_LEFT_IDEOGRAPH_OFFSETS,
        pointer,
    )
}

fn gbk_other_decode(pointer: u16) -> u16 {
    map_with_ranges(
        &GBK_OTHER_POINTERS[..GBK_OTHER_POINTERS.len() - 1],
        &GBK_OTHER_UNSORTED_OFFSETS,
        pointer,
    )
}

fn gb2312_other_decode(pointer: u16) -> u16 {
    map_with_ranges(
        &GB2312_OTHER_POINTERS[..GB2312_OTHER_POINTERS.len() - 1],
        &GB2312_OTHER_UNSORTED_OFFSETS,
        pointer,
    )
}

