#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_gb18030_two_byte_four_byte_and_errors() {
        assert_eq!(decode_gb18030(b"plain,123").0.as_ref(), "plain,123");
        assert!(!decode_gb18030(b"plain,123").1);

        // 0x80 -> 欧元符号；GB2312 汉字；GBK 扩展汉字；GB18030 四字节 BMP 与 Astral 平面
        let sample = [
            0x80, 0xA1, 0xA1, // € + 全角空格
            0xB3, 0xC7, 0xCA, 0xD0, // 城市
            0x81, 0x40, // 丂 (GBK 顶部扩展区)
            0xFE, 0x7E, // 龹 / GB18030-2022 映射验证 (0xFE,0x7E -> U+9FB9)
            0x81, 0x35, 0xF4, 0x37, // U+E7C7
            0x94, 0x39, 0xDA, 0x33, // U+1F4A9 (💩)
        ];
        let (decoded, had_errors) = decode_gb18030(&sample);
        assert!(!had_errors);
        assert_eq!(
            decoded.as_ref(),
            "€\u{3000}城市\u{4E02}\u{9FB9}\u{E7C7}\u{1F4A9}"
        );

        // 非法序列恢复：4 字节第 3 字节为 ASCII 时应保留第 2 字节 ASCII
        let (recovered, err_rec) = decode_gb18030(&[0x81, 0x30, b'A']);
        assert!(err_rec);
        assert_eq!(recovered.as_ref(), "\u{FFFD}0A");

        // 4 字节在 EOF 处截断：整体替换为一个 U+FFFD
        let (eof_trunc, err_eof) = decode_gb18030(&[0x81, 0x30]);
        assert!(err_eof);
        assert_eq!(eof_trunc.as_ref(), "\u{FFFD}");

        // 0xFF 非法首字节
        let (bad_ff, err_ff) = decode_gb18030(&[0xFF, b'x']);
        assert!(err_ff);
        assert_eq!(bad_ff.as_ref(), "\u{FFFD}x");
    }

    #[test]
    fn decodes_utf16_le_be_with_surrogates_and_errors() {
        // 合法代理对 + ASCII
        let (le, le_err) = decode_utf16_le(&[0x00, 0xD8, 0x00, 0xDC, 0x41, 0x00]);
        assert!(!le_err);
        assert_eq!(le, "\u{10000}A");

        let (be, be_err) = decode_utf16_be(&[0xD8, 0x00, 0xDC, 0x00, 0x00, 0x41]);
        assert!(!be_err);
        assert_eq!(be, "\u{10000}A");

        // 孤立代理项与奇数字节
        let (bad_le, bad_le_err) = decode_utf16_le(&[0x00, 0xD8, 0x41, 0x00, 0xFF]);
        assert!(bad_le_err);
        assert_eq!(bad_le, "\u{FFFD}A\u{FFFD}");
    }
}
